#include "../Source/PluginProcessor.h"
#include <iostream>
#include <new>
#include <cstdlib>
static bool watch=false;static int allocations=0;
void* operator new(std::size_t n){if(watch)++allocations;if(auto* p=std::malloc(n))return p;throw std::bad_alloc();}void operator delete(void* p)noexcept{std::free(p);}void operator delete(void* p,std::size_t)noexcept{std::free(p);}
static void check(bool b,const char* s){if(!b){std::cerr<<"FAIL "<<s<<'\n';std::exit(1);}}
int main(int argc,char** argv){juce::ScopedJuceInitialiser_GUI init;auto ptr=std::make_unique<PrismProcessor>();auto& p=*ptr;juce::StringArray names;for(auto* a:p.getParameters()){check(!names.contains(a->getName(100)),"unique parameter names");names.add(a->getName(100));}check(names.size()==39,"39 parameters");
 for(int i=0;i<16;++i){p.setCurrentProgram(i);check(!p.getProgramName(i).isEmpty(),"factory names");}
 for(int mode=0;mode<3;++mode){juce::AudioProcessor::BusesLayout l;l.inputBuses.add(mode==2?juce::AudioChannelSet::stereo():juce::AudioChannelSet::mono());l.outputBuses.add(mode==0?juce::AudioChannelSet::mono():juce::AudioChannelSet::stereo());check(p.setBusesLayout(l),"channel layouts");p.prepareToPlay(48000,256);}
 p.setValue("diffusionOn",1);p.setValue("diffusionType",2);p.setValue("diffusionAmount",1);p.setValue("characterOn",0);p.setValue("movementOn",0);p.setValue("textureOn",0);p.prepareToPlay(96000,256);p.prepareToPlay(48000,256);juce::AudioBuffer<float> b(2,256);juce::MidiBuffer midi;b.clear();b.setSample(0,0,.5f);p.processBlock(b,midi);p.reset();p.prepareToPlay(48000,1024);double tails=0;for(int n=0;n<300;++n){b.clear();p.processBlock(b,midi);for(int c=0;c<2;++c)for(int i=0;i<256;++i)tails+=std::abs(b.getSample(c,i));}check(tails>1e-5,"reset and same-rate prepare retain tails");
 p.setValue("characterAmount",.713f);p.queue(prism::Action::CaptureRecord);for(int block=0;block<20;++block){for(int n=0;n<256;++n){b.setSample(0,n,.1f);b.setSample(1,n,-.1f);}p.processBlock(b,midi);}p.queue(prism::Action::CapturePlay);b.clear();p.processBlock(b,midi);p.saveSlot(79);juce::MemoryBlock state;p.getStateInformation(state);check(state.getSize()>1000,"state contains audio");p.setValue("characterAmount",.1f);check(p.restore(state.getData(),int(state.getSize())),"valid bank restore");check(std::abs(p.value("characterAmount")-.713f)<.002,"parameter restore");p.loadSlot(79);check(p.getCurrentProgram()==95,"user slot80 recall");check(p.engine.capture.seconds()>.1,"session capture retained");
 auto fresh=std::make_unique<PrismProcessor>();check(fresh->restore(state.getData(),int(state.getSize())),"pre-init restore");fresh->prepareToPlay(96000,256);check(std::abs(fresh->engine.capture.seconds()-5120./48000)<.001,"capture sample-rate migration");
 for(int cut:{0,1,7,15,40,int(state.getSize())-1}){float old=p.value("characterAmount");check(!p.restore(state.getData(),cut),"truncated state rejected");check(old==p.value("characterAmount"),"failed state import atomic");}juce::MemoryBlock corrupt(state);static_cast<unsigned char*>(corrupt.getData())[4]=99;check(!p.restore(corrupt.getData(),int(corrupt.getSize())),"future version rejected");
 auto bank=juce::File::getSpecialLocation(juce::File::tempDirectory).getNonexistentChildFile("prism-check",".wolfprism");check(p.saveFile(bank).wasOk()&&p.loadFile(bank).wasOk(),"portable bank roundtrip");bank.deleteFile();
 midi.addEvent(juce::MidiMessage::controllerEvent(1,22,127),32);midi.addEvent(juce::MidiMessage::controllerEvent(1,22,0),200);b.clear();p.processBlock(b,midi);check(p.engine.capture.seconds()>.003&&p.engine.capture.seconds()<.004,"sample accurate capture MIDI");
 for(int size:{1,7,64,257,1024,4096}){b.setSize(2,size);b.clear();p.processBlock(b,midi);}
 watch=true;for(int n=0;n<10;++n){b.clear();p.processBlock(b,midi);}watch=false;check(allocations==0,"no wrapper callback heap allocations");
 std::unique_ptr<juce::AudioProcessorEditor> e(p.createEditor());check(e&&e->getWidth()==820,"native editor");if(argc>1){auto snap=[&](juce::String name){auto img=e->createComponentSnapshot(e->getLocalBounds());auto out=juce::File(name).createOutputStream();check(bool(out),"snapshot file");juce::PNGImageFormat png;check(png.writeImageToStream(img,*out),"snapshot native editor");};snap(argv[1]);for(auto* c:e->getChildren())if(auto* btn=dynamic_cast<juce::TextButton*>(c))if(btn->getButtonText()=="FX SETUP"){btn->onClick();snap(juce::String(argv[1]).upToLastOccurrenceOf(".",false,false)+"-setup.png");}}
 std::cout<<"PASS host: 39 unique parameters, 16 factories, 80 slots, mono/stereo, reset tails, session/capture/bank/pre-init recall, sample-rate migration, malformed-state atomic rejection, sample-accurate capture MIDI, block sizes, native editor.\n";
}
